function build(){cleanup();run.maxForce=Math.max(run.maxForce||0,run.force);for(const o of run.objects)if(o.type==='gate'&&o.rowGate&&o.live){o.growing=true;o.blockShots=true;o.halfWidth=.975;delete o.collectAt;o.gateReady=false;}if(combatBand()===7)for(const o of run.objects)if(o.escort)o.stopZ=-1.2;const bossSpec=stageSpec().objects.find(o=>o.boss);for(const o of run.objects)if(o.boss&&bossSpec){o.closeAssault=bossSpec.closeAssault;o.stopZ=bossSpec.stopZ;o.approach=bossSpec.approach;if(o.bossKind==='supply'){o.attackPattern=bossSpec.attackPattern;o.plateWeakSide=o.plateWeakSide||1;}}const theme=stageSpec().theme;terrain.set(theme?.kind||'outpost');mats.road.color.set(theme?.road||'#879696');mats.sand.color.set(theme?.sand||'#b2baa3');scene.background.set(theme?.fog||'#b9bea9');scene.fog.color.set(theme?.fog||'#b9bea9');camera.position.set(0,18,22);camera.lookAt(0,0,-2);camera.fov=42;camera.updateProjectionMatrix();dress();run.objects.forEach(o=>visual(o));for(let i=0;i<Math.min(run.force,DISPLAY_LIMIT);i++){const a=factory.make(run.aim+(i%2?.5:-.5),5+Math.floor(i/5)*.6,'blue',(i*.173)%1);const saved=run.actors?.[i];if(saved){a.model.position.x=saved.x;a.model.position.z=saved.z;a.action.time=saved.t;a.gaitTime=saved.gaitTime??saved.t;}actors.push(a)}flagTier=-1;refreshFlag();for(const b of run.bullets||[])emitVisual(b);$('#hud').hidden=false;$('#progress').hidden=false;$('#band').textContent=stageSpec().band||`作戦 ${run.stage+1} / 100`;$('#mission').textContent=stageSpec().name;$('#panel').hidden=true;$('#hint').textContent=stageSpec().tip;frames=[];}
function start(stage,spec=null,kind='campaign'){audioOn();spec=structuredClone(spec||STAGES[stage]);const objects=spec.objects.map((o,id)=>({...o,id,z:5-o.d,maxHp:o.hp??null,phaseTime:0,phase:'shield',cycle:-1,baseX:o.x,active:!Number.isFinite(o.spawnAt),live:true,clock:0,warn:0,shotX:0,attacks:0}));run={id:crypto.randomUUID(),stage,spec,kind,dailyDay:spec.dailyDay,dailySlot:spec.dailySlot,t:0,distance:0,force:spec.startForce||3,armor:0,aim:0,shots:0,hits:0,telemetry:[],sampleAt:0,kills:0,rescues:0,damage:0,ending:0,resumePhase:'playing',objects,events:[],actors:[],bullets:[]};build();mode='playing';run.deployTime=.85;spectacle.deploy();toast('');snapshot();}
function restore(legacy=false){profile=store.read();const cp=legacy?profile.legacyCheckpoint:profile.checkpoint;if(!cp||!Array.isArray(cp.objects)){toast('途中データを開けません。元データは保持しています');return;}run=structuredClone(cp);if(legacy){run.kind='legacy';run.spec={...structuredClone(LEGACY_STAGES[run.stage]),bandIndex:run.stage,id:'legacy-'+run.stage,areaName:'旧試遊版'};}if(!run.spec){toast('途中データの作戦を確認できません');return;}build();mode='paused';run.resumePhase=cp.phase==='ending'?'ending':'playing';if(run.resumePhase==='ending')for(const a of actors)a.celebrate();restored=true;pausePanel(legacy?'旧試遊版の戦闘を再開':'中断した位置から再開');$('#resume').click();}
