let flagTier=-1,flag=null;function refreshFlag(){const next=tier();if(!actors.length)return;if(flag&&flagTier===next&&flag.parent===actors[0].model)return;if(flag){flag.parent?.remove(flag);flag.traverse(m=>{if(m.isMesh){m.geometry.dispose();if(!Object.values(mats).includes(m.material))m.material.dispose();}})}flag=null;flagTier=next;if(!next)return;flag=new T.Group();const pole=new T.Mesh(new T.CylinderGeometry(.045,.045,3.2,5),mats.metal);pole.position.y=2;flag.add(pole);const cloth=new T.Mesh(new T.PlaneGeometry(1.35,.8),new T.MeshStandardMaterial({color:(SKINS.find(s=>s.id===profile.equipped)||SKINS[0]).flag,side:T.DoubleSide,emissive:[0,0x062744,0x063b30,0x493008][next]}));cloth.position.set(.64,3.15,0);flag.add(cloth);flag.position.set(-.45,0,-.2);actors[0].model.add(flag);}
