const commandFoot=mesh(new T.RingGeometry(.70,.80,40),new T.MeshBasicMaterial({color:0xffe3a0,transparent:true,opacity:.9,side:T.DoubleSide,depthWrite:false,depthTest:false}),0,.095,4.35);commandFoot.renderOrder=7;commandFoot.rotation.x=-Math.PI/2;commandFoot.visible=false;const surgeRing=mesh(new T.RingGeometry(.8,1,48),new T.MeshBasicMaterial({color:0x77ffff,transparent:true,opacity:0,side:T.DoubleSide,depthWrite:false}),0,.08,5);surgeRing.rotation.x=-Math.PI/2;surgeRing.visible=false;let drag=null;renderer.domElement.onpointerdown=e=>{if(mode!=='playing')return;drag={x:e.clientX,aim:run.aim};renderer.domElement.setPointerCapture(e.pointerId);audioOn()};renderer.domElement.onpointermove=e=>{if(drag&&mode==='playing')run.aim=T.MathUtils.clamp(drag.aim+(e.clientX-drag.x)/innerWidth*12,-3.6,3.6)};renderer.domElement.onpointerup=()=>drag=null;renderer.domElement.onpointercancel=()=>drag=null;onresize=()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)};renderer.setAnimationLoop(()=>{const dt=Math.min(clock.getDelta(),.05);commandFoot.visible=mode==='playing';if(run)commandFoot.position.x=run.aim;for(const a of lobbyActors)if(a.update(dt,true,mode==='shop')&&mode==='shop'){a.muzzle();sound('shot',1)}step(dt);battleAudio.tick(mode==='playing'||mode==='audio-settings',!!run?.climax,!!run?.objects.some(o=>o.boss&&o.live&&o.active!==false));renderer.render(scene,camera)});function stageSpec(){return run?.spec||STAGES[run?.stage||0];}
