function storageFailure(e){toast('保存できません。元データは保持しています');console.error(e);}
async function act(button,fn,after){if(button?.disabled)return;if(button)button.disabled=true;try{const x=await store.transaction(fn);profile=x.profile;after?.(x.result);}catch(e){const out=$('#shopMessage')||$('#metaMessage');if(out)out.textContent=e.message;else toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}}
function canResumeLegacy(){return profile.migration?.source===OLD_KEY&&profile.legacyCheckpoint&&Array.isArray(profile.legacyCheckpoint.objects)&&Number.isInteger(profile.legacyCheckpoint.stage)&&!!LEGACY_STAGES[profile.legacyCheckpoint.stage];}
function migrationMenu(){panel(`<small>これまでの部隊を引き継ぎました</small><h2>100の新しい作戦へ</h2><p>所持合金 ${profile.migration.balance} は、同額のコインへ。購入済み塗装・部隊旗・旧作戦の記録も保管しています。</p><p>新100作戦は01から始まります。旧10作戦を新しい作戦のクリア扱いにはしていません。</p>${profile.legacyCheckpoint?'<p>旧途中データは別枠で保管。対応する戦闘は隊員メニューから再開できます。</p>':''}<button class="primary" id="ackMigration">確認して司令部へ</button><p id="metaMessage" role="status"></p>`);$('#ackMigration').onclick=()=>act($('#ackMigration'),p=>{p.migration.acknowledged=true;},menu);}
function moreMenu(){cleanup();mode='menu';profile=store.read();panel(`<small>隊員メニュー</small><h2>部隊のひと息</h2><button id="login">ログインの贈りもの · 累計${profile.login.count}回</button><button id="audioSettings">音量を調整</button><button id="records">旧試遊版の記録</button><button id="home">司令部へ</button>`);$('#login').onclick=loginMenu;$('#audioSettings').onclick=audioMenu;$('#records').onclick=legacyMenu;$('#home').onclick=menu;}
function legacyMenu(){cleanup();mode='menu';panel(`<small>保管された記録</small><h2>旧試遊版の歩み</h2><p>${Object.keys(profile.legacyRecords).length}/10 作戦突破 · 旧部隊旗 ${profile.badges.filter(x=>x.startsWith('legacy')).length}個</p><p>残高・購入済み外観・旗は新しい部隊に引き継いでいます。旧記録と元の保存データは残しています。</p>${canResumeLegacy()?'<button class="primary" id="resumeLegacy">旧戦闘を続きから</button>':profile.legacyCheckpoint?'<p>この旧形式の途中記録は保管されていますが、再開には対応していません。</p>':''}<button id="home">戻る</button>`);$('#resumeLegacy')?.addEventListener('click',()=>restore(true));$('#home').onclick=moreMenu;}
function nextResetLabel(){const now=new Date(),next=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+1));return new Intl.DateTimeFormat(undefined,{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(next)+'（端末時刻）';}
function loginMenu(){cleanup();datedScreen='login';screenDay=utcDay();mode='menu';profile=store.read();const day=utcDay(),slot=profile.login.count%7,claimed=profile.login.days.includes(day);panel(`<small>ログインの贈りもの · 次回 ${nextResetLabel()}</small><h2>また会えて、うれしい</h2><p>1日1回、累計7回。休んだ日があってもリセットされません。</p><div class="login-track">${[20,20,25,25,30,30,'星巡り隊'].map((x,i)=>`<div class="${i<slot?'received':''}"><b>${i+1}回</b><span>${i===6&&profile.owned.includes('starlight')?'60コイン':typeof x==='number'?x+'コイン':x}</span></div>`).join('')}</div><button class="primary" id="claimLogin" ${claimed?'disabled':''}>${claimed?'今日は受け取り済み':(slot+1)+'回目を受け取る'}</button><p id="metaMessage" role="status"></p><p class="muted">7回目の外観は1度だけ。2巡目以降の7回目は60コイン。作戦クリアが主なコイン獲得方法です。</p><button id="home">戻る</button>`);$('#claimLogin').onclick=()=>act($('#claimLogin'),p=>claimLogin(p,utcDay()),r=>{loginMenu();$('#metaMessage').textContent=r.claimed?(r.skin?'星巡り隊を獲得！':r.amount+'コインを受け取りました'):'今日は受け取り済みです';});$('#home').onclick=moreMenu;}
function dailyMenu(){cleanup();datedScreen='daily';screenDay=utcDay();mode='menu';profile=store.read();const day=utcDay(),record=profile.daily[day],open=dailyUnlocked(profile);panel(`<small>特別作戦 · 次回 ${nextResetLabel()}</small><h2>今日の3つの寄り道</h2><p>短い3作戦を1日1セット。初期性能は固定、外観は自由。本編の進行には必須ではありません。</p>${open?`<div class="daily-list">${DAILY_NAMES.map((name,i)=>`<button data-daily="${i}"><b>${name}</b><span>${record?.done.includes(i)?'達成済み · 再挑戦無料':'初回25コイン'}</span></button>`).join('')}</div><p>3作戦達成で追加25コイン ${record?.bonus?'✓':''}</p>`:'<p class="locked-card">本編010・最初のエリア突破で解放</p>'}<p class="muted">毎日更新。中断した作戦の報酬は開始日の枠に1度だけ記録されます。</p><button id="home">司令部へ</button>`);document.querySelectorAll('[data-daily]').forEach(b=>b.onclick=()=>{if(utcDay()!==day){dailyMenu();toast('新しい日の特別作戦に更新しました');return;}const slot=+b.dataset.daily,spec=dailyStage(day,slot);start(spec.bandIndex*10+3,spec,'daily');});$('#home').onclick=menu;}
function audioMenu(){cleanup();mode='audio-settings';profile=store.read();const a=profile.audio;panel(`<small>音の設定</small><h2>好みの音量で出撃</h2><p>BGMと効果音を別々に調整できます。</p>${['bgm','se'].map(k=>`<label class="volume-label">${k==='bgm'?'BGM':'効果音・警告'} <output id="${k}Value">${Math.round(a[k]*100)}%</output><input id="${k}Volume" type="range" min="0" max="100" value="${Math.round(a[k]*100)}"></label><label class="mute-label"><input id="${k}Mute" type="checkbox" ${a[k+'Muted']?'checked':''}>ミュート</label>`).join('')}<button id="testSound">連射・着弾を試す</button><p id="metaMessage" role="status"></p><button id="home">戻る</button>`);for(const k of ['bgm','se']){const update=()=>{const value=+$('#'+k+'Volume').value/100,muted=$('#'+k+'Mute').checked;$('#'+k+'Value').textContent=Math.round(value*100)+'%';profile.audio[k]=value;profile.audio[k+'Muted']=muted;audioOn();store.transaction(p=>{p.audio[k]=value;p.audio[k+'Muted']=muted;}).then(x=>profile=x.profile).catch(storageFailure);};$('#'+k+'Volume').oninput=update;$('#'+k+'Mute').onchange=update;}$('#testSound').onclick=()=>{audioOn();sound('shot',4);setTimeout(()=>sound('hit'),160);};$('#home').onclick=moreMenu;audioOn();}
